-- M153 P4 — conhecimento regulatório versionado e candidatos PharmaLens. Aplicar separadamente.
alter table public.medication_catalog_versions add column if not exists source_updated_at timestamptz,add column if not exists content_hash text,add column if not exists superseded_at timestamptz;
create table if not exists public.medication_catalog_candidates(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,person_id uuid not null references public.persons(id) on delete cascade,medication_id text,acquisition_id text,candidate_kind text not null check(candidate_kind in('presentation','manufacturer','regulatory_class','prescription_model','package')),normalized_payload jsonb not null default '{}'::jsonb,source_kind text not null check(source_kind in('pharmalens','package_scan','leaflet_scan','prescription_scan','manual')),evidence_ref text,status text not null default 'pending' check(status in('pending','officially_verified','rejected','superseded')),official_source_version_id uuid references public.medication_catalog_versions(id) on delete set null,event_date date not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,person_id,candidate_kind,source_kind,evidence_ref));
create index if not exists medication_catalog_candidates_owner_idx on public.medication_catalog_candidates(user_id,person_id,status,created_at desc);alter table public.medication_catalog_candidates enable row level security;drop policy if exists medication_catalog_candidates_owner on public.medication_catalog_candidates;create policy medication_catalog_candidates_owner on public.medication_catalog_candidates for all to authenticated using((select auth.uid())=user_id and exists(select 1 from public.persons p where p.id=person_id and p.user_id=(select auth.uid()))) with check((select auth.uid())=user_id and exists(select 1 from public.persons p where p.id=person_id and p.user_id=(select auth.uid())));grant select,insert,update,delete on public.medication_catalog_candidates to authenticated;
comment on table public.medication_catalog_candidates is 'Candidatos privados extraídos pelo PharmaLens; nunca promovidos automaticamente ao catálogo global.';
